namespace Microsoft.Agents.AI;

/// <summary>
/// An <see cref="AIContextProvider"/> that gives agents todo list management capabilities, allowing an agent to
/// track the steps of a complex, multi-step task within a session.
/// </summary>
/// <remarks>
/// <para>
/// The provider exposes five function tools to the agent: <c>AddTodos</c>, <c>CompleteTodos</c>, <c>RemoveTodos</c>,
/// <c>GetRemainingTodos</c>, and <c>GetAllTodos</c>.
/// </para>
/// <para>
/// State is persisted in the <see cref="AgentSession.StateBag"/> under the key <c>"TodoProvider"</c> and therefore
/// survives across multiple invocations of the same session.
/// </para>
/// </remarks>
public sealed class TodoProvider : AIContextProvider
{
    private const string StateKey = "TodoProvider";

    private const string InstructionsText =
        "You have access to a todo list to help you track and manage the steps of complex, multi-step tasks. " +
        "Use the AddTodos tool to record the steps you plan to take, CompleteTodos to mark steps as done as you finish them, " +
        "RemoveTodos to discard steps that are no longer relevant, GetRemainingTodos to review the outstanding work, " +
        "and GetAllTodos to review the full list including completed items. " +
        "Keep the todo list up to date as you make progress.";

    private readonly ProviderSessionState<TodoState> _sessionState;

    /// <summary>
    /// Initializes a new instance of the <see cref="TodoProvider"/> class.
    /// </summary>
    public TodoProvider()
    {
        this._sessionState = new ProviderSessionState<TodoState>(
            _ => new TodoState(),
            StateKey,
            AgentJsonUtilities.DefaultOptions);
    }

    /// <inheritdoc />
    public override IReadOnlyList<string> StateKeys { get; } = [StateKey];

    /// <inheritdoc />
    protected override ValueTask<AIContext> ProvideAIContextAsync(AIContextProvider.InvokingContext context, CancellationToken cancellationToken = default)
    {
        _ = Throw.IfNull(context);

        var session = context.Session;

        var factoryOptions = new AIFunctionFactoryOptions { SerializerOptions = AgentJsonUtilities.DefaultOptions };

        AITool[] tools =
        [
            AIFunctionFactory.Create(
                (List<TodoItemInput> todos) => this.AddTodos(session, todos),
                new AIFunctionFactoryOptions
                {
                    Name = "AddTodos",
                    Description = "Adds one or more items to the todo list.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                (List<int> ids) => this.CompleteTodos(session, ids),
                new AIFunctionFactoryOptions
                {
                    Name = "CompleteTodos",
                    Description = "Marks the todo items with the specified ids as complete. Returns the number of items updated.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                (List<int> ids) => this.RemoveTodos(session, ids),
                new AIFunctionFactoryOptions
                {
                    Name = "RemoveTodos",
                    Description = "Removes the todo items with the specified ids from the list. Returns the number of items removed.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                () => this.GetRemainingTodos(session),
                new AIFunctionFactoryOptions
                {
                    Name = "GetRemainingTodos",
                    Description = "Gets the todo items that have not yet been completed.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
            AIFunctionFactory.Create(
                () => this.GetAllTodos(session),
                new AIFunctionFactoryOptions
                {
                    Name = "GetAllTodos",
                    Description = "Gets all todo items, including those that have been completed.",
                    SerializerOptions = AgentJsonUtilities.DefaultOptions,
                }),
        ];

        _ = factoryOptions;

        return new ValueTask<AIContext>(new AIContext
        {
            Instructions = InstructionsText,
            Tools = tools,
        });
    }

    /// <summary>
    /// Gets all todo items associated with the specified session, regardless of completion status.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved. May be <see langword="null"/>.</param>
    /// <returns>A read-only list of all todo items. Returns an empty list for a session with no prior state.</returns>
    public IReadOnlyList<TodoItem> GetAllTodos(AgentSession? session)
    {
        var state = this._sessionState.GetOrInitializeState(session);
        return state.Items.ToList();
    }

    /// <summary>
    /// Gets the todo items associated with the specified session that have not yet been completed.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved. May be <see langword="null"/>.</param>
    /// <returns>A list of todo items where <see cref="TodoItem.IsComplete"/> is <see langword="false"/>.</returns>
    public List<TodoItem> GetRemainingTodos(AgentSession? session)
    {
        var state = this._sessionState.GetOrInitializeState(session);
        return state.Items.Where(item => !item.IsComplete).ToList();
    }

    private IReadOnlyList<TodoItem> AddTodos(AgentSession? session, List<TodoItemInput> todos)
    {
        var state = this._sessionState.GetOrInitializeState(session);

        var added = new List<TodoItem>();
        if (todos is not null)
        {
            foreach (var todo in todos)
            {
                var item = new TodoItem
                {
                    Id = state.NextId++,
                    Title = todo?.Title ?? string.Empty,
                    Description = todo?.Description,
                    IsComplete = false,
                };
                state.Items.Add(item);
                added.Add(item);
            }
        }

        this._sessionState.SaveState(session, state);
        return added;
    }

    private int CompleteTodos(AgentSession? session, List<int> ids)
    {
        var state = this._sessionState.GetOrInitializeState(session);

        int count = 0;
        if (ids is not null)
